// Parses `key=value` pairs from a query string fragment.
const PAIR = /^([a-z][a-z0-9_]*)=([^&]*)(?:&|$)/i;

export function parsePairs(input: string): Record<string, string> {
  const out: Record<string, string> = {};
  let rest = input;
  while (rest.length > 0) {
    const match = PAIR.exec(rest);
    if (!match) break;
    out[match[1]!] = decodeURIComponent(match[2]!);
    rest = rest.slice(match[0].length);
  }
  return out;
}

