using UnityEngine;
public class Buggy : MonoBehaviour {
  public WheelCollider[] wheels;
  public float motorTorque = 400f, steer = 30f;
  void FixedUpdate() {
    foreach (var w in wheels) { w.motorTorque = Input.GetAxis("Vertical") * motorTorque; }
    wheels[0].steerAngle = wheels[1].steerAngle = Input.GetAxis("Horizontal") * steer;
  }
}

