using UnityEngine;
public class Swimmer : MonoBehaviour {
  public float buoyancy = 9.5f, waterLevel = 0f;
  Rigidbody rb;
  void Awake() { rb = GetComponent<Rigidbody>(); }
  void FixedUpdate() { if (transform.position.y < waterLevel) rb.AddForce(Vector3.up * buoyancy, ForceMode.Acceleration); }
}

